import { ImageResponse } from "next/og";
import { fetchProfileShareCard } from "@/lib/server/profileShareCard";
import { formatWatchMinutesRounded } from "@/lib/server/formatWatchMinutesPlain";
import {
  AvatarFallbackOg,
  BRAND,
  PLUS_JAKARTA_SANS_BOLD_BASE64,
  PLUS_JAKARTA_SANS_EXTRABOLD_BASE64,
  SEENLIST_MARK_BASE64,
  VerifiedBadgeOg,
  decodeBase64Font,
  fetchAvatarDataUri,
} from "@/lib/server/ogShared";

/**
 * PNG pré-gerado (1200×630, mesma matemática do radial-gradient que já
 * estava em CSS — raio, posição e cor idênticos) do brilho de fundo do
 * card. Ver o comentário grande junto da `<img>` que usa isso, logo
 * abaixo — existe porque o `radial-gradient` em CSS, dentro do satori,
 * renderizava diferente do navegador (o `radial-gradient` em si nunca
 * mudou de fórmula, só a forma de entregar o resultado pro satori).
 */
const PROFILE_GLOW_BG_BASE64 =
  "";

/**
 * A PEDIDO (2026-10-08, "tira o link de dentro do card") — rodapé
 * `seenlist.app/u/<username>` removido do card inteiro (não só
 * reposicionado). O mockup aprovado tinha esse texto dentro do card,
 * mas o pedido aqui é explícito: tirar, não mover.
 */

/**
 * REDESIGN (2026-10-08, "estilo Unwind" — mesmo mockup aprovado do
 * card de review, https://claude.ai/artifact/SvYnmVJedKZkRjvXNHbsdm).
 *
 * CORREÇÃO FINAL (2026-10-08, "ainda está com a caixa ao redor. pare
 * de inventar.") — as duas tentativas anteriores erraram a ESTRUTURA,
 * não só o conteúdo das estatísticas: eu tinha inventado um layout de
 * 2 camadas (div externa com `radial-gradient` de fundo + padding 48,
 * contendo um card interno com `background: BRAND.surface` + borda +
 * `border-radius: 28`) — isso É a "caixa ao redor" que o usuário
 * reportou, porque o card de verdade nunca teve essa moldura externa.
 *
 * Fui direto na fonte (ler o HTML/CSS real do artifact aprovado em vez
 * de adivinhar por print) e o card de PERFIL reaproveita a MESMA regra
 * do card de review (`.card-new`/`.glow-bg`/`.content`, já implementado
 * em `app/r/[reviewId]/opengraph-image.tsx`): é uma ÚNICA camada que
 * ocupa o canvas inteiro —
 *   .card-new { background:#070a10; border:1px solid var(--border);
 *     border-radius:20px; overflow:hidden; position:relative }
 *   .glow-bg { position:absolute; inset:0; <dois radial-gradient +
 *     1 linear-gradient escuro>; filter:blur(2px) }
 *   .glow-bg::after { <linear-gradient diagonal, mix-blend:multiply,
 *     opacity:.6> }
 *   .content.profile-new { padding:18px 20px; height:100%;
 *     display:flex; flex-direction:column; justify-content:space-between }
 * — SEM nenhuma camada/moldura por fora disso. Os valores abaixo são
 * os mesmos do CSS do mockup, multiplicados pela escala real
 * (mockup renderiza a prévia em 440×231px; a imagem final é
 * 1200×630px — fator exato 1200/440 = 630/231 = 30/11 ≈ 2.7273),
 * em vez de estimados de novo por print.
 *
 * Mantém a estrutura "Estilo Bingers" já aprovada antes (avatar+nome à
 * esquerda / logo+nome real à direita no topo; fileira de pôsteres) —
 * só ajusta pra bater com o `.card-new` de verdade: 3 estatísticas
 * (número+rótulo empilhados, sem caixa, espaçadas por
 * `justify-content:space-between` do `.content` — não por `marginTop`
 * manual) e rodapé reduzido a só `seenlist.app/u/<username>` (texto
 * puro, sem ícone de link — o mockup aprovado não tem ícone no rodapé
 * do card de perfil).
 *
 * CORREÇÃO (2026-10-08, comparado com o print real do mockup v21 que
 * o usuário aprovou — primeira versão daqui tinha só 2 tiles com
 * caixa de fundo/borda, inventada sem conferir o mockup de novo antes
 * de implementar): as 3 estatísticas de verdade são tempo de tela,
 * EPISÓDIOS assistidos (não "filmes+episódios" somados — por isso
 * `ProfileShareStats` ganhou `episodesWatched` separado de
 * `watchedCount`) e quantidade de AVALIAÇÕES escritas (`reviewsCount`,
 * nova contagem em `profileShareCard.ts`, mesma definição de
 * `reviewsGiven` em `lib/queries/social-counts.ts`). `watchedCount`
 * continua existindo só porque `app/u/[username]/page.tsx` ainda usa
 * ele no texto do `<meta name="description">`.
 *
 * Histórico (2026-10-08): nesta data trocou `loadGoogleFont` por
 * `loadGoogleFontSafe` (mesma causa raiz do "falha universal" do card
 * de review — chamada incondicional, sem try/catch, dentro do
 * `Promise.all`). NA MESMA SESSÃO, ainda no mesmo dia, essa dependência
 * da API ao vivo do Google Fonts foi removida por completo — ver
 * `decodeBase64Font` e o comentário de `PLUS_JAKARTA_SANS_BOLD_BASE64`
 * em `ogShared.tsx` — por decisão explícita do usuário, depois de essa
 * API servir um arquivo de fonte corrompido em produção 3 vezes.
 *

 * `BRAND`/`SEENLIST_MARK_BASE64`/`VerifiedBadgeOg`/`AvatarFallbackOg`
 * agora vêm de `ogShared.tsx` em vez de definições locais duplicadas
 * — eram idênticas (mesma marca, mesmo selo, mesmo fallback de
 * avatar); consolidado numa fonte só pra não divergir se um dos dois
 * arquivos for ajustado no futuro e o outro não.
 */
export const runtime = "edge";
export const alt = "Perfil no SeenList";
export const size = { width: 1200, height: 630 };
export const contentType = "image/png";
// Preview de rede social não precisa de dado em tempo real — 1h evita
// gerar a mesma imagem de novo a cada toque de "atualizar link" de
// quem está testando o compartilhamento.
export const revalidate = 3600;

/**
 * Número+rótulo empilhados, SEM caixa nenhuma — só texto solto, igual
 * ao `.card-new` do mockup aprovado (confirmado lendo o CSS real, não
 * por print). Tamanho de fonte = valor do mockup (20px/11px num card
 * de prévia 440×231) × escala real (30/11) — ver comentário grande no
 * topo do arquivo.
 */
function StatTileOg({ value, label }: { value: string; label: string }) {
  return (
    <div style={{ display: "flex", flexDirection: "column" }}>
      {/* A PEDIDO (2026-10-08, "a fonte é mais próximo de 'black' e no que
          está atual está normal") — peso reduzido de 800 pra 700. Não achei
          erro de carregamento da fonte 800 nos logs da Vercel (nenhum log
          pra essa invocação), então não é a fonte 800 falhando e caindo pra
          negrito sintético por falta de arquivo — é mais um caso do satori
          (motor que gera a imagem) desenhando o MESMO peso declarado mais
          pesado do que o navegador (mesmo padrão já visto no brilho de
          fundo). 700 é o peso que já carrega sem erro nesta rota. */}
      <span style={{ fontSize: 55, fontWeight: 700, color: BRAND.text, lineHeight: 1.15, display: "flex" }}>{value}</span>
      <span style={{ fontSize: 30, color: "#9aa2b5", display: "flex" }}>{label}</span>
    </div>
  );
}

export default async function Image({ params }: { params: Promise<{ username: string }> }) {
  const { username } = await params;
  const card = await fetchProfileShareCard(username);

  // Fontes locais, embutidas em `ogShared.tsx` — sem chamada de rede,
  // sem `loadGoogleFontSafe`, sem possibilidade de vir corrompida (ver
  // comentário completo na declaração de `PLUS_JAKARTA_SANS_BOLD_BASE64`
  // em `ogShared.tsx`). Mantém o mesmo formato (`name`/`data`/`weight`)
  // que `ImageResponse` já esperava, só troca a origem dos bytes.
  const fonts = [
    { name: "Plus Jakarta Sans", data: decodeBase64Font(PLUS_JAKARTA_SANS_BOLD_BASE64), weight: 700 as const },
    { name: "Plus Jakarta Sans", data: decodeBase64Font(PLUS_JAKARTA_SANS_EXTRABOLD_BASE64), weight: 800 as const },
  ];

  // Ver comentário completo em `fetchAvatarDataUri` (`ogShared.tsx`):
  // `avatar_url` pode ser a foto direta do Google (copiada 1x no
  // cadastro), que o `fetch` do satori às vezes não consegue buscar —
  // cai pro mesmo círculo de gradiente + iniciais que `Avatar.tsx` já
  // usa no app normal, nunca um buraco vazio no card.
  const avatarDataUri = card ? await fetchAvatarDataUri(card.avatarUrl) : null;

  // Perfil inexistente ou privado: card genérico de marca — nunca
  // revela que um perfil privado existe com aquele nome, mesma regra
  // da página em si.
  if (!card) {
    return new ImageResponse(
      (
        <div
          style={{
            width: "100%",
            height: "100%",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            background: BRAND.bg,
            fontFamily: "Plus Jakarta Sans",
          }}
        >
          <div style={{ display: "flex", alignItems: "center", gap: 18 }}>
            {/* eslint-disable-next-line @next/next/no-img-element -- marca real do app, embutida como data: URI. Proporção real 1.3125:1 (548×417 recortado) — largura/altura iguais distorcem o logo; 84×64 preserva a proporção. */}
            <img src={`data:image/png;base64,${SEENLIST_MARK_BASE64}`} width={84} height={64} />
            <span style={{ fontSize: 52, fontWeight: 800, color: BRAND.text }}>SeenList</span>
          </div>
        </div>
      ),
      // Fontes locais embutidas (ver `decodeBase64Font`, importado de `ogShared.tsx`) — sempre
      // presentes, nunca mais um array vazio aqui (o bug real do satori
      // travando com "No fonts are loaded" só existia quando as duas
      // fontes vinham da API ao vivo do Google Fonts e podiam falhar).
      { ...size, fonts: [fonts[1]] }
    );
  }

  const { stats } = card;

  return new ImageResponse(
    (
      // .card-new — ÚNICA camada, ocupa o canvas 1200×630 inteiro. SEM
      // moldura/fundo externo por fora disso (essa moldura extra era a
      // "caixa ao redor" reportada — removida).
      <div
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          background: "#070a10",
          border: "3px solid " + BRAND.border,
          borderRadius: 55,
          overflow: "hidden",
          display: "flex",
          fontFamily: "Plus Jakarta Sans",
        }}
      >
        {/* .glow-bg — camada decorativa.
            CORREÇÃO FINAL (2026-10-08, "ainda prefiro o 'no ar' mas não é o
            que aparece quando entro no link") — depois de 2 tentativas de
            ajustar isso via `radial-gradient` em CSS (raio %, 1 `background`
            combinado, 2 `<div>` separados), nenhuma bateu com o preview no
            navegador — inclusive a combinação em 2 `<div>` (código anterior)
            ficou pixel-a-pixel IGUAL à versão anterior de 1 `background` só,
            provando que não era bug de parsing de lista. Recriei a MESMA
            matemática de gradiente (raio, posição, cor, opacidade — nenhum
            valor mudou) pixel a pixel em Python/numpy, exatamente como um
            navegador renderiza (alpha reto, mesma matiz até sumir, sem ir
            pro preto) — e o resultado bateu certinho com o mockup aprovado
            (ver `/tmp/.../glow-live-recreation.png` gerado nesta sessão).
            Ou seja: o `radial-gradient` do satori (motor que gera esta
            imagem) diverge do CSS padrão de navegador pra este caso — não
            encontrei a causa exata dentro do satori (fonte não inspecionável
            sem instalar o pacote, bloqueado nesta sandbox), mas contornei o
            problema de vez: em vez de pedir pro satori interpretar o
            gradiente, uso o resultado já pronto como imagem (ele sabe
            desenhar `<img>` corretamente, isso nunca deu problema). Zero
            CSS de gradiente daqui pra frente — qualquer ajuste futuro de
            cor/posição do brilho precisa regenerar essa imagem (script
            Python salvo nesta sessão), não mexer em `background`/`style`
            aqui. */}
        <img
          src={`data:image/png;base64,${PROFILE_GLOW_BG_BASE64}`}
          width={1200}
          height={630}
          style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%" }}
        />

        {/* .content.profile-new — conteúdo real, acima do glow (z-index via ordem no DOM do satori).
            CORREÇÃO (2026-10-08, print mostrando os pôsteres "vazando" por baixo, cortados pelo
            canto arredondado do card) — `padding` em shorthand junto com `height:"34%"` na fileira
            de pôsteres (abaixo) não respeitava o espaço reservado pelo `justify-content:space-between`
            dentro do satori (motor que gera a imagem, suporte a CSS limitado/instável nessa combinação
            específica — shorthand + % + space-between). Troquei o padding pra valores explícitos por
            lado e a altura da fileira de pôsteres por um valor fixo em pixel (ver comentário lá embaixo),
            tirando a ambiguidade. */}
        <div
          style={{
            position: "relative",
            width: "100%",
            height: "100%",
            display: "flex",
            flexDirection: "column",
            justifyContent: "space-between",
            paddingTop: 49,
            paddingBottom: 49,
            paddingLeft: 55,
            paddingRight: 55,
          }}
        >
          {/* Topo: avatar + nome à esquerda, logo+nome real à direita — inalterado do design "Estilo Bingers" já aprovado antes */}
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 27 }}>
              {avatarDataUri ? (
                // eslint-disable-next-line @next/next/no-img-element -- `ImageResponse` (satori) não suporta `next/image`, precisa de `<img>` cru.
                <img
                  src={avatarDataUri}
                  width={98}
                  height={98}
                  style={{ borderRadius: 999, border: "5px solid rgba(255,255,255,0.25)", objectFit: "cover" }}
                />
              ) : (
                <AvatarFallbackOg name={card.displayName} size={98} />
              )}
              <div style={{ display: "flex", flexDirection: "column", justifyContent: "center", gap: 3 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  {/* mesma correção da StatTileOg acima — 800 pra 700, ver comentário lá */}
                  <span style={{ fontSize: 41, fontWeight: 700, color: BRAND.text, display: "flex" }}>{card.displayName}</span>
                  {card.verifiedTier && <VerifiedBadgeOg tier={card.verifiedTier} size={34} />}
                </div>
                <span style={{ fontSize: 30, color: "#c3c9d6", display: "flex" }}>{`@${card.username}`}</span>
              </div>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
              {/* eslint-disable-next-line @next/next/no-img-element -- proporção real 1.3125:1 (548×417 recortado); 44×34 preserva a proporção, igual ao .brand-new do mockup (ícone 16px × escala 2.7273). */}
              <img src={`data:image/png;base64,${SEENLIST_MARK_BASE64}`} width={44} height={34} style={{ borderRadius: 11 }} />
              <span style={{ fontSize: 35, fontWeight: 800, color: BRAND.text, display: "flex" }}>SeenList</span>
            </div>
          </div>

          {/* Estatísticas — 3, nessa ordem, igual ao mockup v21 aprovado ("7 meses / de tela", "7.904 / episódios", "612 / avaliações"); espaçadas pelo justify-content:space-between do pai, sem marginTop manual */}
          {stats && (
            <div style={{ display: "flex", gap: 60 }}>
              <StatTileOg value={formatWatchMinutesRounded(stats.watchMinutes)} label="de tela" />
              <StatTileOg value={stats.episodesWatched.toLocaleString("pt-BR")} label="episódios" />
              <StatTileOg value={stats.reviewsCount.toLocaleString("pt-BR")} label="avaliações" />
            </div>
          )}

          {/* Fileira de pôsteres — .poster-row-new.wide do mockup: proporcionalmente ~34% da altura do card, gap 16, cantos 19, borda clara fina, sombra suave; só os que existem de verdade em cache (ver `fetchProfileShareCard`).
              CORREÇÃO (2026-10-08, print do deploy mostrando o rodapé coberto pelos pôsteres) — faltava `height` explícita no <img>; só com `flex: 1` (sem altura), o satori usa a proporção natural do pôster (alto, ~2:3), que estourava além do espaço reservado.
              CORREÇÃO (2026-10-08, print seguinte mostrando os pôsteres cortados pelo canto arredondado do card) — `height:"34%"` nesta fileira, dentro do `justify-content:space-between` do pai, não ficava contida no espaço — altura trocada por um valor fixo em pixel (210, equivalente a ~34% dos ~630px de altura do card descontando o padding), igual ao <img> logo abaixo (também fixo, não mais `"100%"`, que dependia dessa altura percentual do pai). */}
          {card.posterUrls.length > 0 && (
            <div style={{ display: "flex", gap: 16, alignItems: "stretch", height: 210 }}>
              {card.posterUrls.map((url, index) => (
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  key={index}
                  src={url}
                  style={{
                    flex: 1,
                    height: 210,
                    borderRadius: 19,
                    border: "3px solid rgba(255,255,255,.14)",
                    boxShadow: "0 11px 27px -14px rgba(0,0,0,.5)",
                    objectFit: "cover",
                  }}
                />
              ))}
            </div>
          )}
        </div>
      </div>
    ),
    // Fontes locais embutidas — ver `decodeBase64Font`, importado de `ogShared.tsx`.
    { ...size, fonts }
  );
}
